const goal = 480_000;
const quarterEnd = Date.UTC(2026, 11, 31);
const dayMs = 86_400_000;

const revenueSeries: MovementSeries[] = [
  { key: "newMrr", label: "New", color: "var(--ts-chart-1)", sign: 1 },
  {
    key: "expansionMrr",
    label: "Expansion",
